import { cacheLife, cacheTag } from 'next/cache'

export type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

export async function getDashboardData() {
  'use cache'
  cacheLife('minutes')
  cacheTag('dashboard')
  const res = await fetch('https://api.example.com/dashboard')
  return res.json() as Promise<DashboardData>
}

export function CardStats({
  totalRevenue,
  totalInvoices,
}: {
  totalRevenue: number
  totalInvoices: number
}) {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-busy="true">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>—</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>—</p>
      </div>
    </div>
  )
}

export async function CardStatsSection() {
  const { totalRevenue, totalInvoices } = await getDashboardData()
  return <CardStats totalRevenue={totalRevenue} totalInvoices={totalInvoices} />
}

